(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.EloTeam=api;})(typeof window==='undefined'?globalThis:window,()=>{
  'use strict';
  const types={lawyer:'Advogado(a)',intern:'Estagiário(a)',other:'Colaborador(a)'};
  const roles={admin:'Administrador',reviewer:'Revisão e gestão de casos',collaborator:'Casos atribuídos'};
  const states='AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials=name=>String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
  const when=value=>new Date(value).toLocaleDateString('pt-BR');
  const button=(label,action,id='',style='secondary')=>`<button type="button" class="button ${style}" data-action="${action}" data-id="${escape(id)}">${label}</button>`;
  const pending=i=>!i.accepted_at&&!i.revoked_at;
  const invitationStatus=(i,now=Date.now())=>i.accepted_at?'Aceito':i.revoked_at?'Revogado':new Date(i.expires_at).getTime()<=now?'Expirado':'Aguardando aceite';
  const normalize=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
  function filter(items,query='',type='all'){
    return items.filter(m=>(type==='all'||m.professional_type===type)&&normalize([m.display_name,m.email,m.oab_number,m.oab_state].join(' ')).includes(normalize(query.trim())));
  }
  const identity=m=>`<div class="team-identity"><span class="avatar">${escape(initials(m.display_name||m.email))}</span><div><strong>${escape(m.display_name||m.email)}</strong><small>${escape(m.email)}</small>${m.oab_number?`<small>OAB ${escape(m.oab_state)} · ${escape(m.oab_number)}</small>`:''}</div></div>`;
  function list({members,invites,office,userId,admin,tab='active',query='',type='all'}){
    const rows=filter(tab==='invites'?invites.filter(pending):members.filter(m=>tab==='inactive'?m.removed_at:!m.removed_at),query,type);
    if(!rows.length)return `<div class="team-empty"><span aria-hidden="true">${tab==='invites'?'↗':'♧'}</span><h3>${query||type!=='all'?'Nenhum resultado para esta busca.':tab==='invites'?'Nenhum convite pendente.':tab==='inactive'?'Nenhum acesso desativado.':'Sua equipe começa aqui.'}</h3><p>${query||type!=='all'?'Tente outro nome, e-mail ou função.':tab==='invites'?'Cadastre um advogado ou estagiário para preparar o acesso ao escritório.':tab==='inactive'?'Os integrantes com acesso removido aparecerão aqui. O histórico de trabalho é preservado.':'Cadastre as pessoas que vão trabalhar com você.'}</p></div>`;
    return `<div class="team-table"><div class="team-table-head" aria-hidden="true"><span>INTEGRANTE</span><span>FUNÇÃO E ACESSO</span><span>SITUAÇÃO</span><span></span></div>${rows.map(m=>`<article class="team-row">${identity(m)}<div class="team-role"><strong>${escape(types[m.professional_type]||types.other)}</strong><small>${escape(roles[m.role])}</small></div><div class="team-state"><span class="team-badge ${tab==='active'?'solid':''}">${tab==='invites'?escape(invitationStatus(m)):tab==='inactive'?'Desativado':'Ativo'}</span><small>${tab==='invites'?'Até '+when(m.expires_at):m.user_id===office.responsible_user_id?'Responsável pelo escritório':m.user_id===userId?'Sua conta':tab==='inactive'?'Desde '+when(m.removed_at):'Desde '+when(m.joined_at)}</small></div><div class="team-row-actions">${!admin?'':tab==='invites'?button('Renovar link','renewInvite',m.id,'quiet')+button('Revogar','revokeInvite',m.id,'quiet'):tab==='active'&&m.user_id!==office.responsible_user_id?button('Editar cadastro','editMember',m.user_id,'quiet')+button('Desativar','removeMember',m.user_id,'quiet'):tab==='inactive'?button('Convidar novamente','reinviteMember',m.user_id,'quiet'):''}</div></article>`).join('')}</div>`;
  }
  function render(context){
    const {office,members,invites,admin,tab='active'}=context,active=members.filter(m=>!m.removed_at),waiting=invites.filter(pending),inactive=members.filter(m=>m.removed_at);
    return `<div class="page-heading team-heading"><div><div class="eyebrow">${escape(office.name)} · PESSOAS E ACESSOS</div><h1>Sua equipe, conectada.</h1><p>Advogados e estagiários no mesmo escritório.<br>Cada pessoa com o acesso certo para trabalhar.</p></div>${admin?button('Cadastrar integrante +','invite','','primary'):''}</div>
      <div class="team-stats"><div><span>INTEGRANTES ATIVOS</span><strong>${active.length}</strong></div><div><span>ADVOGADOS</span><strong>${active.filter(m=>m.professional_type==='lawyer').length}</strong></div><div><span>ESTAGIÁRIOS</span><strong>${active.filter(m=>m.professional_type==='intern').length}</strong></div>${admin?`<div><span>CONVITES PENDENTES</span><strong>${waiting.length}</strong></div>`:''}</div>
      <section class="shared-panel team-directory" aria-label="Integrantes do escritório"><div class="team-directory-heading"><div><h2>Pessoas do escritório</h2><p>${admin?'Cadastre, acompanhe e organize os acessos da sua equipe.':'Conheça as pessoas que trabalham com você.'}</p></div>${button('Atualizar','refresh','','quiet')}</div>
      <div class="team-tabs" aria-label="Situação dos integrantes">${[['active','Ativos',active.length],...(admin?[['invites','Convites',waiting.length],['inactive','Desativados',inactive.length]]:[])].map(([key,label,count])=>`<button type="button" data-action="teamTab" data-tab="${key}" aria-pressed="${tab===key}" class="${tab===key?'active':''}">${label}<span>${count}</span></button>`).join('')}</div>
      <div class="team-filters"><label><span class="sr-only">Buscar integrante</span><input id="teamSearch" class="shared-input" type="search" placeholder="Buscar por nome, e-mail ou OAB" value="${escape(context.query)}"></label><label><span class="sr-only">Filtrar por função</span><select id="teamType"><option value="all">Todas as funções</option>${Object.entries(types).map(([key,label])=>`<option value="${key}" ${context.type===key?'selected':''}>${label}</option>`).join('')}</select></label></div>
      <div id="teamList" aria-live="polite">${list(context)}</div>
      ${admin&&tab==='invites'?'<p class="team-footnote">O cadastro fica pendente até a pessoa aceitar o convite com o e-mail informado. Links válidos por 7 dias. Compartilhe o link: o envio automático por e-mail ainda não está disponível.</p>':''}</section>
      <div class="team-bottom"><section class="shared-panel team-permissions"><div class="eyebrow">PERMISSÕES DO ESCRITÓRIO</div><h2>Responsabilidades claras.</h2><div class="team-permission-grid"><div><span>01</span><h3>Administrador</h3><p>Cadastra a equipe, define acessos e gerencia todos os casos do escritório.</p></div><div><span>02</span><h3>Advogado(a)</h3><p>Pode atuar nos casos atribuídos ou receber acesso a todos os casos, com gestão e revisão.</p></div><div><span>03</span><h3>Estagiário(a)</h3><p>Acessa apenas os casos atribuídos. Elabora minutas e envia para revisão, sem aprovar entregas.</p></div></div><p class="form-help">A aprovação da minuta exige outro responsável. A função profissional, sozinha, não concede poderes de administrador.</p></section>
      ${admin?`<aside class="team-onboarding"><div class="eyebrow">DO CADASTRO AO ACESSO</div><h2>Três passos.<br>Uma equipe.</h2><ol><li><strong>Cadastre a pessoa</strong><span>Informe os dados e escolha o acesso.</span></li><li><strong>Compartilhe o convite</strong><span>Envie o link pelo canal do escritório.</span></li><li><strong>Acompanhe o aceite</strong><span>A pessoa entra com sua própria conta.</span></li></ol></aside>`:''}</div>
      ${admin&&tab==='invites'&&invites.some(i=>!pending(i))?`<details class="team-history"><summary>Histórico de convites</summary>${invites.filter(i=>!pending(i)).map(i=>`<div><span>${escape(i.display_name||i.email)}</span><span>${escape(invitationStatus(i))} · ${when(i.accepted_at||i.revoked_at)}</span></div>`).join('')}</details>`:''}`;
  }
  function form(m=null,{editing=false}={}){
    const kind=m?.professional_type==='other'?'other':m?.professional_type||'lawyer',role=m?.role==='reviewer'?'reviewer':'collaborator';
    return `<form id="${editing?'memberForm':'inviteForm'}" class="shared-form team-form" ${editing?`data-id="${escape(m.user_id)}"`:''}>
      <p class="team-form-intro">${editing?'Atualize os dados e o acesso desta pessoa ao escritório.':'Cadastre os dados profissionais e prepare um convite pessoal para entrar no escritório.'}</p>
      <fieldset><legend><span>01</span> Identificação</legend><label>Nome completo<input name="display_name" required minlength="2" maxlength="120" autocomplete="off" placeholder="Nome e sobrenome" value="${escape(m?.display_name)}"></label><label>E-mail de acesso<input name="email" type="email" required maxlength="254" autocomplete="off" placeholder="nome@escritorio.com.br" value="${escape(m?.email)}" ${editing?'readonly':''}></label><p class="form-help">${editing?'O e-mail identifica a conta pessoal e não pode ser alterado pelo escritório.':'A pessoa deverá entrar ou criar uma conta com este mesmo e-mail.'}</p></fieldset>
      <fieldset><legend><span>02</span> Função profissional</legend><label>Função no escritório<select name="professional_type"><option value="lawyer" ${kind==='lawyer'?'selected':''}>Advogado(a)</option><option value="intern" ${kind==='intern'?'selected':''}>Estagiário(a)</option>${kind==='other'?'<option value="other" selected>Colaborador(a) · cadastro anterior</option>':''}</select></label><div class="form-row team-oab" ${kind!=='lawyer'?'hidden':''}><label>Número da OAB<input name="oab_number" maxlength="20" placeholder="Ex.: 123456" value="${escape(m?.oab_number)}" ${kind==='lawyer'?'required':'disabled'}></label><label>UF da OAB<select name="oab_state" ${kind==='lawyer'?'required':'disabled'}><option value="">Selecione</option>${states.map(s=>`<option ${m?.oab_state===s?'selected':''}>${s}</option>`).join('')}</select></label></div><p class="form-help" data-oab-note ${kind!=='lawyer'?'hidden':''}>O registro informado será salvo no cadastro; não há validação automática na OAB.</p></fieldset>
      <fieldset><legend><span>03</span> Permissão de acesso</legend><label>Acesso aos casos<select name="role"><option value="collaborator" ${role==='collaborator'?'selected':''}>Somente casos atribuídos</option><option value="reviewer" ${role==='reviewer'?'selected':''} ${kind==='intern'?'disabled':''}>Todos os casos · gestão e revisão</option></select></label><div class="team-access-note" data-access-note>${accessNote(kind,role)}</div></fieldset>
      ${!editing?'<p class="form-help">O acesso será ativado após o aceite. Cada integrante define sua própria senha. Nenhum e-mail será enviado automaticamente.</p>':''}
      <div class="form-error" role="alert" tabindex="-1" hidden></div><div class="form-actions">${button('Cancelar','close')}<button class="button primary" type="submit">${editing?'Salvar alterações':'Salvar cadastro e gerar convite'} →</button></div></form>`;
  }
  function accessNote(kind,role){return kind==='intern'?'Estagiários podem iniciar peças para si, elaborar e comentar seus casos e enviá-los para revisão. Não aprovam minutas nem gerenciam a equipe.':role==='reviewer'?'Pode visualizar todos os casos do escritório, criar entregas, atribuir responsáveis e revisar minutas. Não pode cadastrar ou remover integrantes.':'Visualiza somente os casos atribuídos, elabora minutas e envia para revisão. Pode iniciar peças para si. Não pode aprovar entregas ou gerenciar a equipe.';}
  function syncForm(form){
    const kind=form.elements.professional_type.value,lawyer=kind==='lawyer',role=form.elements.role;
    form.querySelector('.team-oab').hidden=!lawyer;form.querySelector('[data-oab-note]').hidden=!lawyer;
    for(const key of ['oab_number','oab_state']){form.elements[key].required=lawyer;form.elements[key].disabled=!lawyer;}
    role.querySelector('[value="reviewer"]').disabled=kind==='intern';if(kind==='intern')role.value='collaborator';
    form.querySelector('[data-access-note]').textContent=accessNote(kind,role.value);
  }
  return {types,roles,filter,pending,invitationStatus,render,list,form,syncForm,accessNote};
});
